class Wizard {
    constructor(protocols) {
        this.protocols = protocols;
    }
    findDuplicatesInTemplates() {
        var path_ = this.protocols._getPath('wizard/duplicate-menu-id');
        return this.protocols.apiGet(path_);
    }
    fetchPotentialTableInputs(templateName) {
        var path_ = this.protocols._getPath('wizard/potential-table-inputs');
        path_ = `${path_}/${templateName}`;
        return this.protocols.apiGet(path_);
    }

    predictInputs(rangeNamesAsCommaSeparatedText, templatePrefix, author, industry, modelType) {
        var path_ = this.protocols._getPath('wizard/predict-inputs');
        path_ = `${path_}/${rangeNamesAsCommaSeparatedText}/${templatePrefix}/${author}/${industry}/${modelType}`;

        return this.protocols.apiGet(path_);
    }
}
export default Wizard;



